import numpy as np

def ridge_fit(X, y, lam):
    X = np.asarray(X, dtype=float)
    y = np.asarray(y, dtype=float)
    if lam < 0:
        raise ValueError("lam must be >= 0")
    d = X.shape[1]
    return np.linalg.solve(X.T @ X + lam * np.eye(d), X.T @ y)

def lasso_1d(c, lam):
    c = float(c)
    if lam < 0:
        raise ValueError("lam must be >= 0")
    return np.sign(c) * max(abs(c) - lam, 0.0)

# ridge_fit([[1,1],[1,2],[1,3]], [2,2,4], 1.0) -> array([0.5, 1.0])
# lasso_1d(5.0, 2.0) -> 3.0, lasso_1d(1.0, 2.0) -> 0.0

import numpy as np

def grad_mse(w, b, x, y):
    x = np.asarray(x, dtype=float)
    y = np.asarray(y, dtype=float)
    r = w * x + b - y
    n = x.size
    return float(2.0 / n * np.sum(x * r)), float(2.0 / n * np.sum(r))


def num_grad(f, x, h):
    return float((f(x + h) - f(x - h)) / (2.0 * h))
